def polyfill(seg1,seg2, mode='strict'):
 # order: start1 -> end1 -> end2 -> start2
 poly=[seg1[0],seg1[-1],seg2[-1],seg2[0]]
 # if self crossing? 
 out=set()
 def inside(x,y):
  ins=False
  for i in range(len(poly)):
   x1,y1=poly[i];x2,y2=poly[(i+1)%len(poly)]
   cr=(x2-x1)*(y-y1)-(y2-y1)*(x-x1)
   if abs(cr)<1e-8 and min(x1,x2)<=x<=max(x1,x2) and min(y1,y2)<=y<=max(y1,y2): return mode!='strict'
   if (y1>y)!=(y2>y):
    xin=x1+(x2-x1)*(y-y1)/(y2-y1)
    if x<xin: ins=not ins
  return ins
 for r in range(16):
  for c in range(16):
   if inside(r,c): out.add((r,c))
 return poly,out
